"""Assemble a standard Homebrew bottle from an already verified, unmodified Folio archive."""
import argparse,pathlib,json,hashlib,tarfile,tempfile,shutil,os,time,gzip,sys
p=argparse.ArgumentParser();p.add_argument('--archive',required=True);p.add_argument('--sha256',required=True);p.add_argument('--target',required=True);p.add_argument('--tag',required=True);p.add_argument('--formula',required=True);p.add_argument('--receipt',required=True);p.add_argument('--output-dir',required=True);p.add_argument('--strategy');p.add_argument('--version',required=True);p.add_argument('--source-commit',required=True);a=p.parse_args()
archive=pathlib.Path(a.archive);assert hashlib.sha256(archive.read_bytes()).hexdigest()==a.sha256
out=pathlib.Path(a.output_dir);out.mkdir(parents=True,exist_ok=True)
with tempfile.TemporaryDirectory(prefix='qubicsdata-folio-bottle-',dir='/tmp') as folder:
 root=pathlib.Path(folder);unpack=root/'unpack';unpack.mkdir()
 with tarfile.open(archive) as t:t.extractall(unpack)
 source=next(unpack.iterdir());m=json.loads((source/'release.json').read_text());assert m['target']==a.target and m['source_commit']==a.source_commit and m['version']==a.version and m['source_dirty'] is False and m['license']=='Apache-2.0'
 def verify_tree(path):
  actual={str(x.relative_to(path)) for x in path.rglob('*') if x.is_file() or x.is_symlink()};assert actual==set(m['files'])|set(m['links'])|{'release.json','SHA256SUMS'}
  for n,v in m['files'].items():assert not (path/n).is_symlink() and hashlib.sha256((path/n).read_bytes()).hexdigest()==v['sha256']
  for n,v in m['links'].items():assert (path/n).is_symlink() and os.readlink(path/n)==v and (path/n).resolve().is_relative_to(path.resolve())
 verify_tree(source)
 keg=root/'Cellar/folio-workspace'/a.version;keg.mkdir(parents=True);shutil.move(str(source),str(keg/'libexec'));(keg/'bin').mkdir();(keg/'.brew').mkdir();shutil.copy2(a.formula,keg/'.brew/folio-workspace.rb')
 for n in ('folio','folio-server'):(keg/'bin'/n).symlink_to('../libexec/bin/'+n)
 strategy=pathlib.Path(a.strategy) if a.strategy else pathlib.Path(a.formula).parent.parent/'lib/github_private_release_download_strategy.rb';strategy_sha=hashlib.sha256(strategy.read_bytes()).hexdigest();assert strategy_sha=='e455e992349b182e59ebf7fcce934aca60ad0cb4f0ffae5b98d1ea6d9152fc28';(keg/'.brew/lib').mkdir();shutil.copy2(strategy,keg/'.brew/lib/github_private_release_download_strategy.rb');embedded_formula=keg/'.brew/folio-workspace.rb';original_formula_sha=hashlib.sha256(embedded_formula.read_bytes()).hexdigest();formula_text=embedded_formula.read_text();assert '  bottle do' not in formula_text, 'Use clean prebottle formula';assert 'version \"'+a.version+'\"' in formula_text;old_require='require_relative "../lib/github_private_release_download_strategy"';assert old_require in formula_text;embedded_formula.write_text(formula_text.replace(old_require,'require_relative "lib/github_private_release_download_strategy"',1));embedded_formula_sha=hashlib.sha256(embedded_formula.read_bytes()).hexdigest()
 receipt=json.loads(pathlib.Path(a.receipt).read_text());receipt.update(arch='arm64' if a.target.endswith('arm64') else 'x86_64',compiler='none',built_prefix=str(root),built_as_bottle=True,poured_from_bottle=False,changed_files=[],linkage_files=[],binary_relocation_files=[],source_modified_time=1,time=None,qubicsdata_binary_assembly={'mode':'untouched verified prebuilt archive; no compilation','archive':archive.name,'archive_sha256':a.sha256,'artifact_source_commit':m['source_commit'],'target':a.target,'bottle_tag':a.tag});receipt['source']['path']='.brew/folio-workspace.rb';receipt['source']['versions']['stable']=a.version;receipt['source']['versions']['head']=None;(keg/'INSTALL_RECEIPT.json').write_text(json.dumps(receipt,indent=2)+'\n');verify_tree(keg/'libexec')
 dest=out/('folio-workspace-'+a.version+'.'+a.tag+'.bottle.tar.gz')
 with tarfile.open(dest,'w:gz') as t:t.add(keg,arcname='folio-workspace/'+a.version)
 sha=hashlib.sha256(dest.read_bytes()).hexdigest();(out/(dest.name+'.sha256')).write_text(sha+'  '+dest.name+'\n')
 report={'ok':True,'bottle':dest.name,'sha256':sha,'bytes':dest.stat().st_size,'target':a.target,'tag':a.tag,'cellar':'any_skip_relocation','assembly':'standard Homebrew bottle layout from a verified unmodified prebuilt archive; no compilation','source_commit':m['source_commit'],'source_dirty':False,'archive_sha256':a.sha256,'payload_manifest_verified_before_and_after_assembly':True,'embedded_private_strategy_sha256':strategy_sha,'source_formula_sha256':original_formula_sha,'embedded_formula_sha256':embedded_formula_sha,'metadata_patch':'Embedded formula only: require_relative lib/github_private_release_download_strategy; strategy stored under .brew/lib to avoid shared prefix links','built_on':receipt['built_on'],'native_acceptance':False if a.target.endswith('x64') else True,'installation_acceptance':'pending actual Homebrew pour/test'};(out/(dest.name+'.assembly.json')).write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report))
